)

var (
	// appRE and machineRE are internal/machines' app name and machine ID
	// rules.
	appRE  = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)
	nameRE = regexp.MustCompile(`^[a-z0-9_]{1,30}$`)
	zoneRE = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9:._-]{0,127}$`)
)

// State is the reconciler's view of a volume. Growing, restoring and
// attaching show in the spec and status fields and need no state of their
// own.
type State string

const (
	// StateCreating: the record exists and OCI has not confirmed the volume.
	StateCreating State = "creating"
	// StateCreated: the OCI volume is available.
	StateCreated State = "created"
	// StatePendingDestroy: destroy was requested; the OCI volume still exists.
	StatePendingDestroy State = "pending_destroy"
	// StateDestroyed: the OCI volume is deleted. Nothing changes afterwards.
	StateDestroyed State = "destroyed"
	// StateFailed: the OCI volume is lost or unusable and needs an operator.
	StateFailed State = "failed"
)

// transitions lists the states each state may move to.
var transitions = map[State][]State{
	StateCreating:       {StateCreated, StateFailed},
	StateCreated:        {StateFailed, StatePendingDestroy},
	StateFailed:         {StateCreated, StatePendingDestroy},
	StatePendingDestroy: {StateDestroyed},
	StateDestroyed:      nil,
}

// NewID returns a fresh canonical ULID for a volume.
func NewID() string { return entityid.New() }

// Destroying reports whether destroy was requested.
func (v Volume) Destroying() bool { return !v.DestroyRequestedAt.IsZero() }

// Validate checks the shape of one record.
func (v Volume) Validate() error {
	switch {
	case v.SchemaVersion != SchemaVersion:
		return fmt.Errorf("%w: schema version %d", ErrInvalid, v.SchemaVersion)
	case !entityid.Valid(v.ID):
		return fmt.Errorf("%w: id %q", ErrInvalid, v.ID)
	case !appRE.MatchString(v.App):
		return fmt.Errorf("%w: app %q", ErrInvalid, v.App)
	case !nameRE.MatchString(v.Name):
		return fmt.Errorf("%w: name %q must be 1 to 30 of a-z, 0-9 and _", ErrInvalid, v.Name)
	case !validRegion(v.Region):
		return fmt.Errorf("%w: region %q", ErrInvalid, v.Region)
	case !zoneRE.MatchString(v.Zone):
		return fmt.Errorf("%w: zone %q", ErrInvalid, v.Zone)
	case v.SizeGB < MinSizeGB || v.SizeGB > MaxSizeGB:
		return fmt.Errorf("%w: size must be %d to %d GB", ErrInvalid, MinSizeGB, MaxSizeGB)
	case v.VPUsPerGB < 0 || v.VPUsPerGB > maxVPUsPerGB || v.VPUsPerGB%10 != 0:
		return fmt.Errorf("%w: vpus_per_gb must be 0 to %d in steps of 10", ErrInvalid, maxVPUsPerGB)
	case v.SnapshotRetentionDays < 1 || v.SnapshotRetentionDays > maxSnapshotRetentionDays:
		return fmt.Errorf("%w: snapshot retention must be 1 to %d days", ErrInvalid, maxSnapshotRetentionDays)
	case v.MachineID != "" && !entityid.Valid(v.MachineID):
		return fmt.Errorf("%w: machine %q", ErrInvalid, v.MachineID)
	case v.CreatedAt.IsZero():
		return fmt.Errorf("%w: no creation time", ErrInvalid)
	}
	if v.Destroying() && v.MachineID != "" {
		return fmt.Errorf("%w: a destroying volume has no machine", ErrInvalid)
	}
	return v.Status.validate(v.Destroying())
}

func (s Status) validate(destroying bool) error {
	if _, ok := transitions[s.State]; !ok {
		return fmt.Errorf("%w: state %q", ErrInvalid, s.State)
	}
	switch {
	case s.OCID != "" && !isOCID(s.OCID, "volume"):
		return fmt.Errorf("%w: status ocid %q", ErrInvalid, s.OCID)
	case s.State == StateCreated && s.OCID == "":
		return fmt.Errorf("%w: a created volume has an OCID", ErrInvalid)
	case s.SizeGB != 0 && (s.SizeGB < MinSizeGB || s.SizeGB > MaxSizeGB):
		return fmt.Errorf("%w: status size", ErrInvalid)
	case s.AttachedMachineID != "" && (!entityid.Valid(s.AttachedMachineID) || s.OCID == ""):
		return fmt.Errorf("%w: attached machine %q", ErrInvalid, s.AttachedMachineID)
	case len(s.Message) > maxMessageBytes:
		return fmt.Errorf("%w: status message is too long", ErrInvalid)
	case (s.State == StatePendingDestroy || s.State == StateDestroyed) && !destroying:
		return fmt.Errorf("%w: %s without a destroy request", ErrInvalid, s.State)
	case s.State == StateDestroyed && s.AttachedMachineID != "":
		return fmt.Errorf("%w: a destroyed volume is attached", ErrInvalid)
	}
	return nil
}

func validRegion(region string) bool {
	_, ok := catalog.LookupName(region)
	return ok
}

// isOCID is internal/oci's OCID rule.
func isOCID(value, kind string) bool {
	return strings.HasPrefix(value, "ocid1."+kind+".") && len(value) <= 255 && !strings.ContainsAny(value, " \t\r\n")
}

func checkUpdate(prev, next Volume) error {
	if err := next.Validate(); err != nil {
		return err
	}
	fail := func(format string, args ...any) error {
		return fmt.Errorf("%w: volume %s: %s", ErrTransition, prev.ID, fmt.Sprintf(format, args...))
	}
	switch {
	case prev.Status.State == StateDestroyed:
		return fail("it is destroyed")
	case next.ID != prev.ID || next.App != prev.App || next.Name != prev.Name || next.Region != prev.Region ||
		next.Zone != prev.Zone || !next.CreatedAt.Equal(prev.CreatedAt):
		return fail("its identity and zone never change")
	case next.SizeGB < prev.SizeGB || next.Status.SizeGB < prev.Status.SizeGB:
		return fail("it only grows")
	case prev.Destroying() && !next.DestroyRequestedAt.Equal(prev.DestroyRequestedAt):
		return fail("a destroy request is final")
	case prev.MachineID != "" && (next.MachineID != "" && next.MachineID != prev.MachineID || next.Destroying()):
		return fail("it is held by machine %s; release it first", prev.MachineID)
	case next.Status != prev.Status && (next.Status.Epoch == 0 || next.Status.Epoch < prev.Status.Epoch):
		return fail("its status was written at epoch %d; a status write needs that epoch or later", prev.Status.Epoch)
	case prev.Status.OCID != "" && next.Status.OCID != prev.Status.OCID:
		return fail("its OCI volume never changes")
	case next.Status.State != prev.Status.State && !slices.Contains(transitions[prev.Status.State], next.Status.State):
		return fail("state %s cannot become %s", prev.Status.State, next.Status.State)
	}
	return nil
}

// systemPaths are pseudo-filesystems a volume never covers.
var systemPaths = []string{"/dev", "/proc", "/run", "/sys"}

func (m Mount) validate() error {
	clean := path.Clean(m.Path)
	if !entityid.Valid(m.Volume) || !path.IsAbs(m.Path) || clean != m.Path || clean == "/" || len(m.Path) > 255 ||
		strings.ContainsFunc(m.Path, func(r rune) bool { return r <= ' ' || r == ':' || r == 0x7f }) {
		return fmt.Errorf("%w: mount %q at %q needs a volume ID and a clean absolute path", ErrInvalid, m.Volume, m.Path)
	}
	for _, system := range systemPaths {
		if clean == system || strings.HasPrefix(clean, system+"/") {
			return fmt.Errorf("%w: mount path %q is under %s", ErrInvalid, m.Path, system)
		}
	}
	return nil
}

var (
	entropy = ulid.Monotonic(rand.Reader, 0)
	mu      sync.Mutex
)

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func LookupName(name string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Name() == name {
			return entry, true
		}
	}
	return Entry{}, false
}

var testSettings = Settings{CompartmentID: "ocid1.compartment.oc1..workload", Zone: testZone,
	KMSKeyID: "ocid1.key.oc1.sa-saopaulo-1.vault.key1"}

type testFence struct {
	epoch  atomic.Uint64
	leader atomic.Bool
}

func newFence() *testFence {
	fence := &testFence{}
	fence.epoch.Store(7)
	fence.leader.Store(true)
	return fence
}

func (f *testFence) Current() authority.Snapshot {
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true, Leader: f.leader.Load(), Epoch: f.epoch.Load(), Revision: 1,
		ExpiresAt: time.Now().Add(time.Hour)}
}

func (f *testFence) Guard(_ context.Context, epoch uint64) error {
	if !f.leader.Load() || epoch != f.epoch.Load() {
		return authority.ErrFenced
	}
	return nil
}

// fakeCloud is an in-memory OCI Block Volume API. A create whose retry token
// was seen returns the first volume, as OCI does.
type fakeCloud struct {
	mu          sync.Mutex
	volumes     map[string]CloudVolume
	tokens      map[string]string
	policies    []BackupPolicy
	assignments map[string]Assignment
	calls       []string
	loseCreate  bool
	// onGet changes what GetVolume reads, as a change after a listing does.
	onGet func(*CloudVolume)
	seq   int
}

func newFakeCloud() *fakeCloud {
	return &fakeCloud{volumes: map[string]CloudVolume{}, tokens: map[string]string{}, assignments: map[string]Assignment{}}
}

func (c *fakeCloud) next(kind string) string {
	c.seq++
	return fmt.Sprintf("ocid1.%s.oc1.sa-saopaulo-1.f%d", kind, c.seq)
}

func (c *fakeCloud) mutations() []string {
	c.mu.Lock()
	defer c.mu.Unlock()
	var out []string
	for _, call := range c.calls {
		if !strings.HasPrefix(call, "get") && !strings.HasPrefix(call, "list") && !strings.HasPrefix(call, "assignment") {
			out = append(out, call)
		}
	}
	return out
}

// settle finishes every OCI work request.
func (c *fakeCloud) settle() {
	c.mu.Lock()
	defer c.mu.Unlock()
	for id, v := range c.volumes {
		if v.State == "PROVISIONING" {
			v.State = "AVAILABLE"
			c.volumes[id] = v
		}
	}
}

func (c *fakeCloud) put(v CloudVolume) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.volumes[v.ID] = v
}

func (c *fakeCloud) ListVolumes(_ context.Context, compartmentID, zone string) ([]CloudVolume, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "list")
	var out []CloudVolume
	for _, v := range c.volumes {
		if v.CompartmentID == compartmentID && v.Zone == zone {
			v.ETag = ""
			out = append(out, v)
		}
	}
	return out, nil
}

func (c *fakeCloud) GetVolume(_ context.Context, id string) (CloudVolume, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "get")
	v, ok := c.volumes[id]
	if !ok {
		return CloudVolume{}, ErrGone
	}
	v.Tags = maps.Clone(v.Tags)
	if c.onGet != nil {
		c.onGet(&v)
	}
	return v, nil
}

func (c *fakeCloud) CreateVolume(_ context.Context, request CreateRequest) (CloudVolume, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "create")
	if id, ok := c.tokens[request.RetryToken]; ok {
		return c.volumes[id], nil
	}
	v := CloudVolume{ID: c.next("volume"), CompartmentID: request.CompartmentID, Zone: request.Zone,
		SizeGB: request.SizeGB, VPUsPerGB: request.VPUsPerGB, KMSKeyID: request.KMSKeyID,
		State: "PROVISIONING", ETag: "e1", Tags: maps.Clone(request.Tags)}
	c.volumes[v.ID], c.tokens[request.RetryToken] = v, v.ID
	if c.loseCreate {
		return CloudVolume{}, errors.New("create response lost")
	}
	return v, nil
}

func (c *fakeCloud) update(id, etag, call string, change func(*CloudVolume)) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, call)
	v, ok := c.volumes[id]
	if !ok || v.ETag != etag {
		return errors.New("precondition failed")
	}
	change(&v)
	v.ETag += "+"
	c.volumes[id] = v
	return nil
}

func (c *fakeCloud) ResizeVolume(_ context.Context, id, etag string, sizeGB int64) error {
	return c.update(id, etag, fmt.Sprintf("resize %d", sizeGB), func(v *CloudVolume) { v.SizeGB = sizeGB })
}

func (c *fakeCloud) SetVolumePerformance(_ context.Context, id, etag string, vpus int) error {
	return c.update(id, etag, fmt.Sprintf("vpus %d", vpus), func(v *CloudVolume) { v.VPUsPerGB = vpus })
}

func (c *fakeCloud) ListBackupPolicies(context.Context, string) ([]BackupPolicy, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "list policies")
	return append([]BackupPolicy(nil), c.policies...), nil
}

func (c *fakeCloud) CreateBackupPolicy(_ context.Context, _ string, policy BackupPolicy, _ string) (BackupPolicy, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "create policy "+policy.Name)
	policy.ID = c.next("volumebackuppolicy")
	c.policies = append(c.policies, policy)
	return policy, nil
}

func (c *fakeCloud) PolicyAssignment(_ context.Context, volumeID string) (Assignment, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "assignment")
	return c.assignments[volumeID], nil
}

func (c *fakeCloud) AssignPolicy(_ context.Context, volumeID, policyID string) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "assign "+policyID)
	if c.assignments[volumeID].ID != "" {
		return errors.New("volume already has a backup policy")
	}
	c.assignments[volumeID] = Assignment{ID: c.next("volumebackuppolicyassignment"), PolicyID: policyID}
	return nil
}

func (c *fakeCloud) DeleteAssignment(_ context.Context, assignmentID string) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, "unassign")
	for volumeID, assignment := range c.assignments {
		if assignment.ID == assignmentID {
			delete(c.assignments, volumeID)
		}
	}
	return nil
}

func testReconciler(t *testing.T) (*Reconciler, *fakeCloud, *testFence) {
	t.Helper()
	store, _ := testStore(t)
	cloud, fence := newFakeCloud(), newFence()
	return &Reconciler{Store: store, Cloud: cloud, Fencer: fence, Settings: testSettings}, cloud, fence
}

func mustPass(t *testing.T, r *Reconciler) {
	t.Helper()
	if err := r.Pass(t.Context()); err != nil {
		t.Fatal(err)
	}
}

func reload(t *testing.T, r *Reconciler, id string) Volume {
